<div class="mw-scroll"><table class="mw-table"><thead><tr><th>Folio</th><th>Servicio / activo</th><th>Proveedor</th><th>Fecha y hora</th>@unless($calendarList ?? false)<th>Frecuencia</th>@endunless<th>Estado</th><th>Reporte</th><th>Acciones</th></tr></thead><tbody>
@forelse($appointments as $event)
    <tr class="{{ $section === 'programacion' && $selectedAppointment?->id === $event->id ? 'mw-selected' : '' }}"><td>{{ $event->folio }}</td><td>{{ $event->service->service }}<small>{{ $event->asset }} · {{ $event->laboratory->nombre }}</small></td><td>{{ $event->provider?->name ?? 'Sin asignar' }}</td><td class="mw-nowrap">{{ $event->starts_at->format('d/m/Y · H:i') }}</td>@unless($calendarList ?? false)<td>{{ $event->frequency ?: 'Por definir' }}</td>@endunless<td><span class="mw-status {{ $event->status }}">{{ $statusLabels[$event->status] }}</span></td><td><a href="{{ $url(['seccion' => 'programacion', 'seleccion' => $event->id]) }}#maintenance-report">{{ $event->documents->isNotEmpty() ? 'Ver reporte' : $reportLabels[$event->report_status] }}</a></td><td><a class="mw-button mw-small" href="{{ $url(['seccion' => 'programacion', 'seleccion' => $event->id]) }}#maintenance-report">Detalle</a></td></tr>
